'use strict';

const fs = require('node:fs');
const path = require('node:path');

const FILE_NAME = 'todos.json';

const USAGE = `Usage: node index.js <command> [arguments]

Commands:
  add <text>       Add a new todo
  list             List all todos
  complete <id>    Mark a todo as done
  delete <id>      Delete a todo
  help             Show this help
`;

// Expected, user-facing failures. Anything else is a bug and should surface as-is.
class TodoError extends Error {}

function emptyStore() {
  return { nextId: 1, todos: [] };
}

function load(file) {
  let raw;
  try {
    raw = fs.readFileSync(file, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return emptyStore();
    throw new TodoError(`Could not read ${file}: ${err.message}`);
  }
  if (raw.trim() === '') return emptyStore();

  let data;
  try {
    data = JSON.parse(raw);
  } catch {
    throw new TodoError(`${file} is not valid JSON. Fix or remove it and try again.`);
  }

  // Accept a bare array of todos as well as the { nextId, todos } shape we write.
  const todos = Array.isArray(data) ? data : data !== null && typeof data === 'object' ? data.todos : undefined;
  if (!Array.isArray(todos) || !todos.every(isTodo)) {
    throw new TodoError(`${file} is not in the expected format. Fix or remove it and try again.`);
  }

  // Never hand out an id that is already in use, even if nextId was edited by hand.
  const maxId = todos.reduce((max, todo) => Math.max(max, todo.id), 0);
  const nextId = Number.isSafeInteger(data.nextId) && data.nextId > maxId ? data.nextId : maxId + 1;
  return { nextId, todos };
}

function isTodo(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    Number.isSafeInteger(value.id) &&
    value.id > 0 &&
    typeof value.text === 'string'
  );
}

function save(file, store) {
  // Write to a temp file and rename so a crash mid-write can't truncate the real file.
  const tmp = `${file}.${process.pid}.tmp`;
  try {
    fs.writeFileSync(tmp, JSON.stringify(store, null, 2) + '\n');
    fs.renameSync(tmp, file);
  } catch (err) {
    fs.rmSync(tmp, { force: true });
    throw new TodoError(`Could not write ${file}: ${err.message}`);
  }
}

function parseId(value, command) {
  if (value === undefined) {
    throw new TodoError(`Missing todo id. Usage: node index.js ${command} <id>`);
  }
  const id = /^\d+$/.test(value) ? Number(value) : NaN;
  if (!Number.isSafeInteger(id) || id < 1) {
    throw new TodoError(`Invalid id "${value}". Ids are positive integers; run "node index.js list" to see them.`);
  }
  return id;
}

function findTodo(store, id) {
  const index = store.todos.findIndex((todo) => todo.id === id);
  if (index === -1) throw new TodoError(`Todo #${id} not found.`);
  return index;
}

function rejectExtraArgs(command, args, expected) {
  if (args.length > expected) {
    throw new TodoError(`Too many arguments for "${command}". Run "node index.js help" for usage.`);
  }
}

function formatList(todos) {
  if (todos.length === 0) {
    return 'No todos yet. Add one with: node index.js add "<text>"\n';
  }
  const width = String(Math.max(...todos.map((todo) => todo.id))).length;
  const lines = todos.map(
    (todo) => `${String(todo.id).padStart(width)}. [${todo.completed ? 'x' : ' '}] ${todo.text}`
  );
  const done = todos.filter((todo) => todo.completed).length;
  lines.push('', `${todos.length - done} pending, ${done} done`);
  return lines.join('\n') + '\n';
}

function add(file, args, now) {
  const text = args.join(' ').trim();
  if (text === '') {
    throw new TodoError('Missing todo text. Usage: node index.js add "<text>"');
  }
  const store = load(file);
  const todo = { id: store.nextId, text, completed: false, createdAt: now().toISOString() };
  store.todos.push(todo);
  store.nextId += 1;
  save(file, store);
  return `Added todo #${todo.id}: ${todo.text}\n`;
}

function list(file, args) {
  rejectExtraArgs('list', args, 0);
  return formatList(load(file).todos);
}

function complete(file, args) {
  rejectExtraArgs('complete', args, 1);
  const id = parseId(args[0], 'complete');
  const store = load(file);
  const todo = store.todos[findTodo(store, id)];
  if (todo.completed) {
    return `Todo #${id} is already completed: ${todo.text}\n`;
  }
  todo.completed = true;
  save(file, store);
  return `Completed todo #${id}: ${todo.text}\n`;
}

function remove(file, args) {
  rejectExtraArgs('delete', args, 1);
  const id = parseId(args[0], 'delete');
  const store = load(file);
  const [todo] = store.todos.splice(findTodo(store, id), 1);
  save(file, store);
  return `Deleted todo #${id}: ${todo.text}\n`;
}

/**
 * Runs a CLI command and returns its result instead of printing it, so it can be
 * tested in-process. `cwd` controls where todos.json lives; `now` is the clock.
 */
function run(argv, { cwd = process.cwd(), now = () => new Date() } = {}) {
  const [command, ...args] = argv;
  const file = path.join(cwd, FILE_NAME);
  try {
    switch (command) {
      case 'add':
        return ok(add(file, args, now));
      case 'list':
        return ok(list(file, args));
      case 'complete':
        return ok(complete(file, args));
      case 'delete':
        return ok(remove(file, args));
      case 'help':
      case '--help':
      case '-h':
        return ok(USAGE);
      case undefined:
        return { code: 1, stdout: '', stderr: USAGE };
      default:
        throw new TodoError(`Unknown command "${command}".\n\n${USAGE}`);
    }
  } catch (err) {
    if (err instanceof TodoError) {
      return { code: 1, stdout: '', stderr: `Error: ${err.message}\n` };
    }
    throw err;
  }
}

function ok(stdout) {
  return { code: 0, stdout, stderr: '' };
}

module.exports = { run, load, save, parseId, formatList, TodoError, FILE_NAME, USAGE };
'use strict';

// End-to-end tests: spawn the real CLI to check argv handling, streams and exit codes.

const { describe, test, beforeEach, afterEach } = require('node:test');
const assert = require('node:assert/strict');
const { spawnSync } = require('node:child_process');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const INDEX = path.join(__dirname, '..', 'index.js');

let dir;

function cli(...args) {
  const { status, stdout, stderr } = spawnSync(process.execPath, [INDEX, ...args], { cwd: dir, encoding: 'utf8' });
  return { status, stdout, stderr };
}

beforeEach(() => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'todo-cli-'));
});

afterEach(() => {
  fs.rmSync(dir, { recursive: true, force: true });
});

describe('node index.js', () => {
  test('full add → list → complete → delete workflow', () => {
    assert.deepEqual(cli('add', 'Buy groceries'), { status: 0, stdout: 'Added todo #1: Buy groceries\n', stderr: '' });
    assert.equal(cli('add', 'Walk the dog').status, 0);

    assert.deepEqual(cli('complete', '1'), { status: 0, stdout: 'Completed todo #1: Buy groceries\n', stderr: '' });
    assert.equal(cli('list').stdout, '1. [x] Buy groceries\n2. [ ] Walk the dog\n\n1 pending, 1 done\n');

    assert.deepEqual(cli('delete', '1'), { status: 0, stdout: 'Deleted todo #1: Buy groceries\n', stderr: '' });
    assert.equal(cli('list').stdout, '2. [ ] Walk the dog\n\n1 pending, 0 done\n');
  });

  test('stores todos.json in the current working directory', () => {
    cli('add', 'Here');

    const saved = JSON.parse(fs.readFileSync(path.join(dir, 'todos.json'), 'utf8'));
    assert.equal(saved.todos[0].text, 'Here');
    assert.equal(saved.todos[0].completed, false);
    assert.equal(typeof saved.todos[0].createdAt, 'string');
  });

  test('keeps separate lists per directory', () => {
    const other = fs.mkdtempSync(path.join(os.tmpdir(), 'todo-cli-other-'));
    try {
      cli('add', 'In first dir');
      const result = spawnSync(process.execPath, [INDEX, 'list'], { cwd: other, encoding: 'utf8' });
      assert.match(result.stdout, /No todos yet/);
    } finally {
      fs.rmSync(other, { recursive: true, force: true });
    }
  });

  test('prints an empty-list message', () => {
    const result = cli('list');
    assert.equal(result.status, 0);
    assert.match(result.stdout, /No todos yet/);
  });

  test('writes errors to stderr with exit code 1', () => {
    for (const args of [['add'], ['complete'], ['complete', 'abc'], ['delete', '5'], ['bogus']]) {
      const result = cli(...args);
      assert.equal(result.status, 1, `exit code for ${args.join(' ')}`);
      assert.equal(result.stdout, '', `stdout for ${args.join(' ')}`);
      assert.match(result.stderr, /^Error: /, `stderr for ${args.join(' ')}`);
    }
  });

  test('prints usage and exits 1 with no command', () => {
    const result = cli();
    assert.equal(result.status, 1);
    assert.match(result.stderr, /^Usage: node index\.js <command>/);
  });

  test('prints usage and exits 0 for --help', () => {
    const result = cli('--help');
    assert.equal(result.status, 0);
    assert.match(result.stdout, /^Usage: node index\.js <command>/);
  });

  test('treats a dash-prefixed id as invalid rather than as a flag', () => {
    cli('add', 'Task');
    const result = cli('delete', '-1');
    assert.equal(result.status, 1);
    assert.match(result.stderr, /Invalid id "-1"/);
  });
});
'use strict';

const { describe, test, beforeEach, afterEach } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const { run, load, save, parseId, formatList, TodoError, USAGE } = require('../lib/todos');

const FIXED_NOW = new Date('2026-01-02T03:04:05.678Z');

let dir;
let file;

function todo(...argv) {
  return run(argv, { cwd: dir, now: () => FIXED_NOW });
}

function readFile() {
  return JSON.parse(fs.readFileSync(file, 'utf8'));
}

function writeFile(data) {
  fs.writeFileSync(file, typeof data === 'string' ? data : JSON.stringify(data));
}

function assertError(result, pattern) {
  assert.equal(result.code, 1);
  assert.equal(result.stdout, '');
  assert.match(result.stderr, /^Error: /);
  assert.match(result.stderr, pattern);
}

beforeEach(() => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'todo-test-'));
  file = path.join(dir, 'todos.json');
});

afterEach(() => {
  fs.rmSync(dir, { recursive: true, force: true });
});

describe('add', () => {
  test('creates todos.json with a fully populated todo', () => {
    const result = todo('add', 'Buy groceries');

    assert.deepEqual(result, { code: 0, stdout: 'Added todo #1: Buy groceries\n', stderr: '' });
    assert.deepEqual(readFile().todos, [
      { id: 1, text: 'Buy groceries', completed: false, createdAt: '2026-01-02T03:04:05.678Z' },
    ]);
  });

  test('uses the real clock for createdAt by default', () => {
    const before = Date.now();
    run(['add', 'Timed'], { cwd: dir });
    const after = Date.now();

    const { createdAt } = readFile().todos[0];
    assert.equal(new Date(createdAt).toISOString(), createdAt, 'createdAt is an ISO 8601 string');
    const ts = Date.parse(createdAt);
    assert.ok(ts >= before && ts <= after);
  });

  test('assigns auto-incrementing ids', () => {
    todo('add', 'First');
    todo('add', 'Second');
    const result = todo('add', 'Third');

    assert.equal(result.stdout, 'Added todo #3: Third\n');
    assert.deepEqual(readFile().todos.map((t) => [t.id, t.text]), [
      [1, 'First'],
      [2, 'Second'],
      [3, 'Third'],
    ]);
  });

  test('does not reuse the id of a deleted todo', () => {
    todo('add', 'First');
    todo('add', 'Second');
    todo('delete', '2');
    todo('add', 'Third');

    assert.deepEqual(readFile().todos.map((t) => t.id), [1, 3]);
  });

  test('does not reuse ids after every todo is deleted', () => {
    todo('add', 'First');
    todo('delete', '1');
    const result = todo('add', 'Second');

    assert.equal(result.stdout, 'Added todo #2: Second\n');
  });

  test('joins unquoted words into a single todo', () => {
    todo('add', 'Buy', 'some', 'milk');
    assert.equal(readFile().todos[0].text, 'Buy some milk');
  });

  test('trims surrounding whitespace', () => {
    todo('add', '   Walk the dog  ');
    assert.equal(readFile().todos[0].text, 'Walk the dog');
  });

  test('preserves quotes, unicode and JSON-special characters', () => {
    const text = 'Say "hi" to Zoë \\ café 🎉 {"not": "json"}';
    todo('add', text);
    assert.equal(readFile().todos[0].text, text);
    assert.match(todo('list').stdout, /\[ \] Say "hi" to Zoë \\ café 🎉 \{"not": "json"\}/);
  });

  test('errors when text is missing and does not create the file', () => {
    assertError(todo('add'), /Missing todo text/);
    assert.equal(fs.existsSync(file), false);
  });

  test('errors when text is empty or only whitespace', () => {
    assertError(todo('add', ''), /Missing todo text/);
    assertError(todo('add', '   ', '\t'), /Missing todo text/);
    assert.equal(fs.existsSync(file), false);
  });

  test('leaves no temp files behind', () => {
    todo('add', 'One');
    todo('add', 'Two');
    assert.deepEqual(fs.readdirSync(dir), ['todos.json']);
  });
});

describe('list', () => {
  test('reports an empty list when todos.json does not exist', () => {
    const result = todo('list');

    assert.equal(result.code, 0);
    assert.match(result.stdout, /No todos yet/);
    assert.equal(result.stderr, '');
  });

  test('does not create todos.json', () => {
    todo('list');
    assert.equal(fs.existsSync(file), false);
  });

  test('reports an empty list after every todo is deleted', () => {
    todo('add', 'Temporary');
    todo('delete', '1');
    assert.match(todo('list').stdout, /No todos yet/);
  });

  test('shows id, status indicator and text for each todo', () => {
    todo('add', 'Buy groceries');
    todo('add', 'Walk the dog');
    todo('add', 'Write report');
    todo('complete', '2');

    const result = todo('list');

    assert.equal(result.code, 0);
    assert.equal(
      result.stdout,
      ['1. [ ] Buy groceries', '2. [x] Walk the dog', '3. [ ] Write report', '', '2 pending, 1 done', ''].join('\n')
    );
  });

  test('right-aligns ids so text lines up past id 9', () => {
    for (let i = 1; i <= 10; i++) todo('add', `Task ${i}`);

    const lines = todo('list').stdout.split('\n');

    assert.equal(lines[0], ' 1. [ ] Task 1');
    assert.equal(lines[9], '10. [ ] Task 10');
  });

  test('shows todos in id order with gaps from deletions', () => {
    todo('add', 'A');
    todo('add', 'B');
    todo('add', 'C');
    todo('delete', '2');

    assert.match(todo('list').stdout, /^1\. \[ \] A\n3\. \[ \] C\n/);
  });

  test('errors on unexpected extra arguments', () => {
    assertError(todo('list', 'extra'), /Too many arguments for "list"/);
  });
});

describe('complete', () => {
  beforeEach(() => {
    todo('add', 'Buy groceries');
    todo('add', 'Walk the dog');
  });

  test('marks the todo as done and persists it', () => {
    const result = todo('complete', '1');

    assert.deepEqual(result, { code: 0, stdout: 'Completed todo #1: Buy groceries\n', stderr: '' });
    const [first, second] = readFile().todos;
    assert.equal(first.completed, true);
    assert.equal(second.completed, false, 'other todos are untouched');
  });

  test('keeps the other fields of the completed todo intact', () => {
    const before = readFile().todos[0];
    todo('complete', '1');
    assert.deepEqual(readFile().todos[0], { ...before, completed: true });
  });

  test('is a no-op with a notice when the todo is already done', () => {
    todo('complete', '1');
    const before = fs.readFileSync(file, 'utf8');

    const result = todo('complete', '1');

    assert.equal(result.code, 0);
    assert.equal(result.stdout, 'Todo #1 is already completed: Buy groceries\n');
    assert.equal(fs.readFileSync(file, 'utf8'), before);
  });

  test('errors when the id is missing', () => {
    assertError(todo('complete'), /Missing todo id\. Usage: node index\.js complete <id>/);
  });

  for (const bad of ['abc', '0', '-1', '1.5', '1abc', '', ' 1', '0x1', '1e2', '99999999999999999999']) {
    test(`errors on invalid id ${JSON.stringify(bad)}`, () => {
      const before = fs.readFileSync(file, 'utf8');
      assertError(todo('complete', bad), /Invalid id/);
      assert.equal(fs.readFileSync(file, 'utf8'), before, 'file is untouched');
    });
  }

  test('errors when no todo has that id', () => {
    assertError(todo('complete', '99'), /Todo #99 not found/);
    assert.ok(readFile().todos.every((t) => !t.completed));
  });

  test('errors when the todo list is empty', () => {
    fs.rmSync(file);
    assertError(todo('complete', '1'), /Todo #1 not found/);
    assert.equal(fs.existsSync(file), false);
  });

  test('errors on extra arguments instead of guessing', () => {
    assertError(todo('complete', '1', '2'), /Too many arguments for "complete"/);
    assert.ok(readFile().todos.every((t) => !t.completed));
  });

  test('accepts ids with leading zeros', () => {
    assert.equal(todo('complete', '02').stdout, 'Completed todo #2: Walk the dog\n');
  });
});

describe('delete', () => {
  beforeEach(() => {
    todo('add', 'Buy groceries');
    todo('add', 'Walk the dog');
    todo('add', 'Write report');
  });

  test('removes the todo and keeps the rest', () => {
    const result = todo('delete', '2');

    assert.deepEqual(result, { code: 0, stdout: 'Deleted todo #2: Walk the dog\n', stderr: '' });
    assert.deepEqual(readFile().todos.map((t) => t.text), ['Buy groceries', 'Write report']);
  });

  test('can delete a completed todo', () => {
    todo('complete', '1');
    assert.equal(todo('delete', '1').code, 0);
    assert.deepEqual(readFile().todos.map((t) => t.id), [2, 3]);
  });

  test('errors when deleting the same todo twice', () => {
    todo('delete', '1');
    assertError(todo('delete', '1'), /Todo #1 not found/);
  });

  test('errors when the id is missing', () => {
    assertError(todo('delete'), /Missing todo id\. Usage: node index\.js delete <id>/);
  });

  for (const bad of ['abc', '0', '-2', '2.0', 'two']) {
    test(`errors on invalid id ${JSON.stringify(bad)}`, () => {
      assertError(todo('delete', bad), /Invalid id/);
      assert.equal(readFile().todos.length, 3);
    });
  }

  test('errors when no todo has that id', () => {
    assertError(todo('delete', '42'), /Todo #42 not found/);
    assert.equal(readFile().todos.length, 3);
  });

  test('errors when the todo list is empty', () => {
    fs.rmSync(file);
    assertError(todo('delete', '1'), /Todo #1 not found/);
    assert.equal(fs.existsSync(file), false);
  });

  test('errors on extra arguments instead of guessing', () => {
    assertError(todo('delete', '1', '2'), /Too many arguments for "delete"/);
    assert.equal(readFile().todos.length, 3);
  });
});

describe('commands and usage', () => {
  test('prints usage to stderr and fails when no command is given', () => {
    assert.deepEqual(todo(), { code: 1, stdout: '', stderr: USAGE });
  });

  for (const flag of ['help', '--help', '-h']) {
    test(`prints usage to stdout for ${flag}`, () => {
      assert.deepEqual(todo(flag), { code: 0, stdout: USAGE, stderr: '' });
    });
  }

  test('usage mentions every command', () => {
    for (const command of ['add', 'list', 'complete', 'delete']) {
      assert.match(USAGE, new RegExp(`\\b${command}\\b`));
    }
  });

  test('rejects unknown commands with usage', () => {
    const result = todo('remove', '1');
    assertError(result, /Unknown command "remove"/);
    assert.ok(result.stderr.includes(USAGE));
  });

  test('commands are case-sensitive', () => {
    assertError(todo('ADD', 'x'), /Unknown command "ADD"/);
  });
});

describe('storage', () => {
  test('writes pretty-printed JSON with nextId and todos', () => {
    todo('add', 'Buy groceries');

    const raw = fs.readFileSync(file, 'utf8');
    assert.ok(raw.endsWith('\n'));
    assert.ok(raw.includes('\n  "todos": ['), 'is indented');
    assert.deepEqual(JSON.parse(raw), {
      nextId: 2,
      todos: [{ id: 1, text: 'Buy groceries', completed: false, createdAt: FIXED_NOW.toISOString() }],
    });
  });

  test('treats an empty file as an empty list', () => {
    writeFile('');
    assert.match(todo('list').stdout, /No todos yet/);
    todo('add', 'First');
    assert.equal(readFile().todos[0].id, 1);
  });

  test('reads a bare array of todos and continues numbering after the highest id', () => {
    writeFile([
      { id: 4, text: 'Four', completed: false, createdAt: FIXED_NOW.toISOString() },
      { id: 7, text: 'Seven', completed: true, createdAt: FIXED_NOW.toISOString() },
    ]);

    assert.match(todo('list').stdout, /4\. \[ \] Four\n7\. \[x\] Seven/);
    assert.equal(todo('add', 'Eight').stdout, 'Added todo #8: Eight\n');
  });

