'use strict';

const fs = require('node:fs');
const path = require('node:path');

const FILE_NAME = 'todos.json';

const USAGE = `Usage: node index.js <command> [arguments]

Commands:
  add <text>       Add a new todo
  list             List all todos
  complete <id>    Mark a todo as done
  delete <id>      Delete a todo
  help             Show this help
`;

// Expected, user-facing failures. Anything else is a bug and should surface as-is.
class TodoError extends Error {}

function emptyStore() {
  return { nextId: 1, todos: [] };
}

function load(file) {
  let raw;
  try {
    raw = fs.readFileSync(file, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return emptyStore();
    throw new TodoError(`Could not read ${file}: ${err.message}`);
  }
  if (raw.trim() === '') return emptyStore();

  let data;
  try {
    data = JSON.parse(raw);
  } catch {
    throw new TodoError(`${file} is not valid JSON. Fix or remove it and try again.`);
  }

  // Accept a bare array of todos as well as the { nextId, todos } shape we write.
  const todos = Array.isArray(data) ? data : data !== null && typeof data === 'object' ? data.todos : undefined;
  if (!Array.isArray(todos) || !todos.every(isTodo)) {
    throw new TodoError(`${file} is not in the expected format. Fix or remove it and try again.`);
  }

  // Never hand out an id that is already in use, even if nextId was edited by hand.
  const maxId = todos.reduce((max, todo) => Math.max(max, todo.id), 0);
  const nextId = Number.isSafeInteger(data.nextId) && data.nextId > maxId ? data.nextId : maxId + 1;
  return { nextId, todos };
}

function isTodo(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    Number.isSafeInteger(value.id) &&
    value.id > 0 &&
    typeof value.text === 'string'
  );
}

function save(file, store) {
  // Write to a temp file and rename so a crash mid-write can't truncate the real file.
  const tmp = `${file}.${process.pid}.tmp`;
  try {
    fs.writeFileSync(tmp, JSON.stringify(store, null, 2) + '\n');
    fs.renameSync(tmp, file);
  } catch (err) {
    fs.rmSync(tmp, { force: true });
    throw new TodoError(`Could not write ${file}: ${err.message}`);
  }
}

function parseId(value, command) {
  if (value === undefined) {
    throw new TodoError(`Missing todo id. Usage: node index.js ${command} <id>`);
  }
  const id = /^\d+$/.test(value) ? Number(value) : NaN;
  if (!Number.isSafeInteger(id) || id < 1) {
    throw new TodoError(`Invalid id "${value}". Ids are positive integers; run "node index.js list" to see them.`);
  }
  return id;
}

function findTodo(store, id) {
  const index = store.todos.findIndex((todo) => todo.id === id);
  if (index === -1) throw new TodoError(`Todo #${id} not found.`);
  return index;
}

function rejectExtraArgs(command, args, expected) {
  if (args.length > expected) {
    throw new TodoError(`Too many arguments for "${command}". Run "node index.js help" for usage.`);
  }
}

function formatList(todos) {
  if (todos.length === 0) {
    return 'No todos yet. Add one with: node index.js add "<text>"\n';
  }
  const width = String(Math.max(...todos.map((todo) => todo.id))).length;
  const lines = todos.map(
    (todo) => `${String(todo.id).padStart(width)}. [${todo.completed ? 'x' : ' '}] ${todo.text}`
  );
  const done = todos.filter((todo) => todo.completed).length;
  lines.push('', `${todos.length - done} pending, ${done} done`);
  return lines.join('\n') + '\n';
}

function add(file, args, now) {
  const text = args.join(' ').trim();
  if (text === '') {
    throw new TodoError('Missing todo text. Usage: node index.js add "<text>"');
  }
  const store = load(file);
  const todo = { id: store.nextId, text, completed: false, createdAt: now().toISOString() };
  store.todos.push(todo);
  store.nextId += 1;
  save(file, store);
  return `Added todo #${todo.id}: ${todo.text}\n`;
}

function list(file, args) {
  rejectExtraArgs('list', args, 0);
  return formatList(load(file).todos);
}

function complete(file, args) {
  rejectExtraArgs('complete', args, 1);
  const id = parseId(args[0], 'complete');
  const store = load(file);
  const todo = store.todos[findTodo(store, id)];
  if (todo.completed) {
    return `Todo #${id} is already completed: ${todo.text}\n`;
  }
  todo.completed = true;
  save(file, store);
  return `Completed todo #${id}: ${todo.text}\n`;
}

function remove(file, args) {
  rejectExtraArgs('delete', args, 1);
  const id = parseId(args[0], 'delete');
  const store = load(file);
  const [todo] = store.todos.splice(findTodo(store, id), 1);
  save(file, store);
  return `Deleted todo #${id}: ${todo.text}\n`;
}

/**
 * Runs a CLI command and returns its result instead of printing it, so it can be
 * tested in-process. `cwd` controls where todos.json lives; `now` is the clock.
 */
function run(argv, { cwd = process.cwd(), now = () => new Date() } = {}) {
  const [command, ...args] = argv;
  const file = path.join(cwd, FILE_NAME);
  try {
    switch (command) {
      case 'add':
        return ok(add(file, args, now));
      case 'list':
        return ok(list(file, args));
      case 'complete':
        return ok(complete(file, args));
      case 'delete':
        return ok(remove(file, args));
      case 'help':
      case '--help':
      case '-h':
        return ok(USAGE);
      case undefined:
        return { code: 1, stdout: '', stderr: USAGE };
      default:
        throw new TodoError(`Unknown command "${command}".\n\n${USAGE}`);
    }
  } catch (err) {
    if (err instanceof TodoError) {
      return { code: 1, stdout: '', stderr: `Error: ${err.message}\n` };
    }
    throw err;
  }
}

function ok(stdout) {
  return { code: 0, stdout, stderr: '' };
}

module.exports = { run, load, save, parseId, formatList, TodoError, FILE_NAME, USAGE };
