describe('storage', () => {
  test('writes pretty-printed JSON with nextId and todos', () => {
    todo('add', 'Buy groceries');

    const raw = fs.readFileSync(file, 'utf8');
    assert.ok(raw.endsWith('\n'));
    assert.ok(raw.includes('\n  "todos": ['), 'is indented');
    assert.deepEqual(JSON.parse(raw), {
      nextId: 2,
      todos: [{ id: 1, text: 'Buy groceries', completed: false, createdAt: FIXED_NOW.toISOString() }],
    });
  });

  test('treats an empty file as an empty list', () => {
    writeFile('');
    assert.match(todo('list').stdout, /No todos yet/);
    todo('add', 'First');
    assert.equal(readFile().todos[0].id, 1);
  });

  test('reads a bare array of todos and continues numbering after the highest id', () => {
    writeFile([
      { id: 4, text: 'Four', completed: false, createdAt: FIXED_NOW.toISOString() },
      { id: 7, text: 'Seven', completed: true, createdAt: FIXED_NOW.toISOString() },
    ]);

    assert.match(todo('list').stdout, /4\. \[ \] Four\n7\. \[x\] Seven/);
    assert.equal(todo('add', 'Eight').stdout, 'Added todo #8: Eight\n');
  });

  test('never reuses an existing id even if nextId is stale', () => {
    writeFile({ nextId: 2, todos: [{ id: 5, text: 'Five', completed: false, createdAt: FIXED_NOW.toISOString() }] });
    assert.equal(todo('add', 'Next').stdout, 'Added todo #6: Next\n');
  });

  test('reports corrupt JSON without overwriting the file', () => {
    writeFile('{ this is not json');

    assertError(todo('list'), /not valid JSON/);
    assertError(todo('add', 'Anything'), /not valid JSON/);
    assert.equal(fs.readFileSync(file, 'utf8'), '{ this is not json');
