    ['null', 'null'],
    ['an object without todos', '{"items": []}'],
    ['todos without ids', '[{"text": "no id"}]'],
    ['todos with non-integer ids', '[{"id": "1", "text": "string id"}]'],
    ['todos without text', '[{"id": 1}]'],
